import CoreText
import Foundation

// The console look's typeface, built into the app (subset to Latin to keep it small): Barlow
// Condensed (SIL Open Font License 1.1), the narrow caps printed on a desk's panel. The licence
// allows bundling in an app; its text is in Licenses/ in the repository.

enum ConsoleFonts {
    /// PostScript names, for Font.custom.
    static let condensedMedium = "BarlowCondensed-Medium"
    static let condensedSemiBold = "BarlowCondensed-SemiBold"
    static let condensedBold = "BarlowCondensed-Bold"

    private static var registered = false

    /// Call once at launch, before any view draws.
    static func register() {
        guard !registered else { return }
        registered = true
        for encoded in [barlowCondensedMedium, barlowCondensedSemiBold, barlowCondensedBold] {
            guard let data = Data(base64Encoded: encoded),
                  let provider = CGDataProvider(data: data as CFData),
                  let font = CGFont(provider) else { continue }
            CTFontManagerRegisterGraphicsFont(font, nil)
        }
    }

    private static let barlowCondensedMedium = ""

    private static let barlowCondensedSemiBold = ""

    private static let barlowCondensedBold = ""

}
